// cop repulsion for driving: returns {push (add to steer, left/right), front (nearest cop in ahead slices, 50 = none)}
function copAvoid(o) {
  let push = 0, front = 50;
  for (let i = 0; i < 8; i++) {
    const d = o.pie.cop[i];
