// car throttle/brake for a target speed: sets a.gas or a.brake from current speed sa (abs m/s) and want
function driveTo(a, sa, want) {
  if (sa < want) a.gas = 0.8;
  else a.brake = sa > want + 3 ? 0.6 : 0;
  return a;
