// debtor in talk range (person within 2.5 m, or occupied goal car within 4 m)
function inTalkRange(o) {
  const G = o.goal, e = o.enter;
  if (!G) return false;
  return G.kind === 'person' ? G.d < 2.5 : G.kind === 'car' && !G.free && G.d < 4 && !(e && e.goal && e.d < 3);
